import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {execFileSync} from 'node:child_process';
const json=p=>JSON.parse(fs.readFileSync(p));const ids=['saeon','nullroute','sigma','leimma','pharma','runo','vox','cynosure','memoria'];
test('26 September: nine distinct outputs, multilingual public entry and frontier, no acceptance inflation',()=>{const b=json('assets/citizen-work.json'),f=json('assets/research-frontiers.json');const d=b.deliveries.filter(x=>x.executionId==='daily-20260926-root');assert.equal(d.length,9);assert.equal(new Set(d.map(x=>x.citizenId)).size,9);for(const x of d){assert.equal(x.executor,'Codex / root');assert.equal(x.review,null);}for(const id of ids){const n=json(`research/2026-09-26/${id}.json`);assert.equal(n.date,'2026-09-26');for(const l of ['zh','en','ko']){for(const key of ['title','lead','next','limitation','citizenName'])assert(n[key][l]);const a=json(`assets/agents${l==='zh'?'':'.'+l}.json`);assert(a.find(x=>x.id===id).works.find(x=>x.publicationId===`2026-09-26-${id}`).url.includes('lang='+l));assert(f.citizens[id][l].length>=2);assert.equal(f.citizens[id][l][0].publicationId,`2026-09-26-${id}`);}for(const a of n.attachments)assert(fs.statSync(a.path).size>160);}});
test('observed award retains missing delivery and default fields; synthetic forecast cases do not resolve actual cards',()=>{const gate=JSON.parse(execFileSync(process.execPath,['scripts/test-contract-evidence-gates.mjs'],{encoding:'utf8'}));assert.equal(gate.observedPositive,0);const a=json('research/2026-09-26/nullroute-award.json');assert.equal(a.deliveryOrAcceptanceDate,null);const f=json('research/2026-09-26/cynosure-resolution-tests.json');assert.equal(f.rows.length,6);assert(f.rows.every(x=>x.actual===x.expected));assert(f.actualOutcomes.every(x=>x.outcome===null&&x.brier===null));const original=json('research/2026-09-25/cynosure-forecasts.json');assert.deepEqual(original.cards.map(x=>x.probability),[0.65,0.55]);});
test('historical sensitivity summary is reproducible from archived row errors',()=>{const s=json('research/2026-09-26/sigma-sensitivity.json');const calc=(rows,key)=>rows.reduce((a,r)=>a+r[key],0)/rows.length;assert.equal(s.rows.length,8);assert.equal(s.leaveOneYearOut.length,8);for(const r of s.leaveOneYearOut){const subset=s.rows.filter(x=>x.year!==r.omittedYear);assert(Math.abs(r.trendMAPE-calc(subset,'trendAPE'))<1e-10);}assert(s.rows.find(x=>x.year===2009).trendAPE>s.rows.find(x=>x.year===2009).naiveAPE);});
